/* Declared with gint's own font_t so the compiler lays the bitfield
 * byte, the pointers and the trailing metrics out exactly the way
 * gint's renderer reads them. */
static font_t const con_font = {
    "Consolas",
    0, 0, 0, 0,              /* bold, italic, serif, mono */
    0,                       /* prop: fixed-width cell */
    15,                      /* line_height */
    15,                      /* data_height */
    57,                      /* block_count */
    293,                      /* glyph_count */
    0,                       /* char_spacing: advance == 8 px */
    (void *)con_blocks,
    (void *)con_data,
    { .width = 8, .storage_size = 4 }
};

font_t const *con_font_get(void) { return &con_font; }
